def find_orphans(
    contacts: list[dict[str, str]],
    accounts: list[dict[str, str]],
) -> list[str]:
    """Return live orphan contact IDs in ascending primary-key order."""
    live_account_ids = {
        account.get("ACCT_ID", "")
        for account in accounts
        if account.get("DEL_FLG", "") != "Y"
        and account.get("ACCT_ID", "") != ""
    }

    return sorted(
        contact.get("CONT_ID", "")
        for contact in contacts
        if contact.get("DEL_FLG", "") != "Y"
        and (
            contact.get("ACCT_ID", "") == ""
            or contact.get("ACCT_ID", "") not in live_account_ids
        )
    )
